//
// Runs the WebAssembly patient side off the page's main thread, so key
// generation does not freeze the page. The secret key lives only inside this
// worker's WebAssembly memory; no message ever carries it out.

import createRiskClient from "./risk_client.js";

const SETUP_FILES = ["cc.bin", "pk.bin", "mk.bin", "rk.bin"];
const ready = createRiskClient();

self.onmessage = async ({ data: { id, op, args } }) => {
  try {
    const m = await ready;
    let result;
    const transfer = [];
    if (op === "keygen") {
      m.keygen(65536);
      result = {};
      for (const name of SETUP_FILES) {
        result[name] = m.setupFile(name);
        transfer.push(result[name].buffer);
      }
    } else if (op === "check") {
      result = m.checkInputs(...args);
    } else if (op === "encrypt") {
      result = m.encrypt(...args);
      transfer.push(result.buffer);
    } else if (op === "decrypt") {
      result = m.decrypt(new Uint8Array(args[0]));
    } else {
      throw new Error(`unknown op ${op}`);
    }
    self.postMessage({ id, result }, transfer);
  } catch (e) {
    self.postMessage({ id, error: String(e?.message ?? e) });
  }
};
